import fs from 'node:fs/promises';import path from 'node:path';import crypto from 'node:crypto';
export const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
export async function atomic(file,data){const temp=file+'.'+crypto.randomUUID()+'.tmp';await fs.writeFile(temp,JSON.stringify(data,null,2),{mode:0o600});await fs.rename(temp,file);}
export async function initialize(root){for(const d of ['keys','uploads','work','outputs','logs'])await fs.mkdir(path.join(root,d),{recursive:true});const file=path.join(root,'data.json');let state;try{state=JSON.parse(await fs.readFile(file,'utf8'));}catch(e){if(e.code!=='ENOENT')throw e;state={licenses:[],sources:[],jobs:[],audit:[]};await atomic(file,state);}for(const j of state.jobs)if(['running','queued'].includes(j.status))Object.assign(j,{status:'failed',error:'服务重启，任务中断，请重新构建',finishedAt:new Date().toISOString()});await atomic(file,state);let admin;try{admin=JSON.parse(await fs.readFile(path.join(root,'admin.json'),'utf8'));}catch(e){if(e.code!=='ENOENT')throw e;const password=crypto.randomBytes(18).toString('base64url'),salt=crypto.randomBytes(16).toString('hex');admin={username:'admin',salt,hash:crypto.scryptSync(password,salt,32).toString('hex')};await atomic(path.join(root,'admin.json'),admin);await fs.writeFile(path.join(root,'bootstrap-admin.txt'),'用户名：admin\n密码：'+password+'\n首次登录后请修改密码，本文件不进入源码。\n',{mode:0o600});}let keys;try{keys={privateKey:await fs.readFile(path.join(root,'keys/private.pem'),'utf8'),publicKey:await fs.readFile(path.join(root,'keys/public.pem'),'utf8')};}catch(e){if(e.code!=='ENOENT')throw e;const pair=crypto.generateKeyPairSync('ed25519');keys={privateKey:pair.privateKey.export({type:'pkcs8',format:'pem'}),publicKey:pair.publicKey.export({type:'spki',format:'pem'})};await fs.writeFile(path.join(root,'keys/private.pem'),keys.privateKey,{mode:0o600,flag:'wx'});await fs.writeFile(path.join(root,'keys/public.pem'),keys.publicKey,{mode:0o600,flag:'wx'});}let queue=Promise.resolve();const commit=()=>{const snapshot=structuredClone(state);queue=queue.catch(()=>{}).then(()=>atomic(file,snapshot));return queue;};const audit=(action,id)=>{state.audit.unshift({at:new Date().toISOString(),action,id});state.audit.length=Math.min(state.audit.length,500);};return {state,admin,keys,commit,audit};}
